// Package generate renders the Go source file of typed feature constants that
// `go tool entitler generate` writes, so build tooling can call it directly.
package generate

import (
	"bytes"
	"fmt"
	"go/format"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"unicode"

	"github.com/entitlerhq/entitler-go"
)

// Header is the first line of every generated file, in the form Go tools recognise.
const Header = "// Code generated by go tool entitler generate. DO NOT EDIT."

const sourcePrefix = "// Read from "

// Options configures Render.
type Options struct {
	// Package is the generated file's package name.
	Package string
	// Existing is the file being replaced, or nil: each feature it names keeps its constant's
	// name, so adding a feature never renames another.
	Existing []byte
}

// Render writes the constants for the features listed, sorted by key, as gofmt would leave them.
// Text from Entitler is untrusted: it is escaped in comments and literals, and identifiers are
// built from ASCII letters, digits and underscores only.
func Render(list *entitler.FeatureList, opts Options) ([]byte, error) {
	if !token(opts.Package) {
		return nil, fmt.Errorf("pass the package name as a Go identifier")
	}
	features := slices.Clone(list.Features)
	slices.SortFunc(features, func(a, b entitler.FeatureListing) int { return strings.Compare(a.Key, b.Key) })
	names := assignNames(features, KeptNames(opts.Existing))
	byKey := map[string]entitler.FeatureListing{}
	for _, f := range features {
		byKey[f.Key] = f
	}

	var b bytes.Buffer
	b.WriteString(Header + "\n")
	b.WriteString(sourcePrefix + strings.Join(lines(source(list)), " ") + "\n")
	b.WriteString("\npackage " + opts.Package + "\n\n")
	if len(features) > 0 {
		b.WriteString("import \"github.com/entitlerhq/entitler-go\"\n\nvar (\n")
		for i, f := range features {
			if i > 0 {
				b.WriteString("\n")
			}
			b.WriteString(doc(names[f.Key], f))
			b.WriteString(names[f.Key] + " = " + constructor(f, byKey) + "\n")
		}
		b.WriteString(")\n")
	}
	return format.Source(b.Bytes())
}

func token(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		letter := r == '_' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z'
		if !letter && (i == 0 || r < '0' || r > '9') {
			return false
		}
	}
	return true
}

func source(list *entitler.FeatureList) string {
	s := list.Environment.Name + ", " + list.Track.Name
	switch {
	case list.Change != nil:
		s += ", change " + *list.Change
	case list.Release != nil:
		s += ", release " + strconv.FormatInt(*list.Release, 10)
	}
	return s + "."
}

// SameIgnoringSource reports whether two generated files hold the same constants, ignoring the
// "Read from" line, so a new release with the same features stays up to date.
func SameIgnoringSource(a, b []byte) bool {
	strip := func(file []byte) string {
		var out []string
		for line := range strings.SplitSeq(string(file), "\n") {
			if !strings.HasPrefix(line, sourcePrefix) {
				out = append(out, line)
			}
		}
		return strings.Join(out, "\n")
	}
	return strip(a) == strip(b)
}

var constant = regexp.MustCompile(`(?m)^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*entitler\.(?:OnOff|Config|Metered|Group|Key)\(("(?:[^"\\]|\\.)*")`)

// KeptNames answers the feature key each constant in an existing generated file holds, by name.
func KeptNames(file []byte) map[string]string {
	kept := map[string]string{}
	for _, m := range constant.FindAllSubmatch(file, -1) {
		if key, err := strconv.Unquote(string(m[2])); err == nil {
			if _, dup := kept[key]; !dup {
				kept[key] = string(m[1])
			}
		}
	}
	return kept
}

// Count answers how many constants a generated file holds.
func Count(file []byte) int { return len(constant.FindAll(file, -1)) }

var initialisms = map[string]bool{
	"ACL": true, "AMQP": true, "API": true, "ASCII": true, "CPU": true, "CSS": true, "DB": true, "DNS": true, "EOF": true,
	"GID": true, "GUID": true, "HTML": true, "HTTP": true, "HTTPS": true, "ID": true, "IP": true, "JSON": true, "QPS": true,
	"RAM": true, "RPC": true, "RTP": true, "SIP": true, "SLA": true, "SMTP": true, "SQL": true, "SSH": true, "TCP": true,
	"TLS": true, "TS": true, "TTL": true, "UDP": true, "UI": true, "UID": true, "URI": true, "URL": true, "UTF8": true,
	"UUID": true, "VM": true, "XML": true, "XMPP": true, "XSRF": true, "XSS": true,
}

// Name converts a feature key to its constant's name: export_pdf is FeatureExportPdf, and the
// initialisms staticcheck knows are upper case, so support_sla_hours is FeatureSupportSLAHours.
// Only ASCII letters and digits are kept.
func Name(key string) string {
	var b strings.Builder
	b.WriteString("Feature")
	for _, word := range strings.FieldsFunc(key, func(r rune) bool {
		return r >= 128 || !unicode.IsLetter(r) && !unicode.IsDigit(r)
	}) {
		if upper := strings.ToUpper(word); initialisms[upper] {
			b.WriteString(upper)
			continue
		}
		b.WriteString(strings.ToUpper(word[:1]) + strings.ToLower(word[1:]))
	}
	return b.String()
}

// assignNames keeps each existing constant's name, then names the rest in key order, escaping a
// name already taken with _2, _3 and so on.
func assignNames(features []entitler.FeatureListing, kept map[string]string) map[string]string {
	names := map[string]string{}
	taken := map[string]bool{}
	for _, f := range features {
		if name, ok := kept[f.Key]; ok && token(name) && !taken[name] {
			names[f.Key], taken[name] = name, true
		}
	}
	for _, f := range features {
		if _, ok := names[f.Key]; ok {
			continue
		}
		base := Name(f.Key)
		name := base
		for i := 2; taken[name]; i++ {
			name = base + "_" + strconv.Itoa(i)
		}
		names[f.Key], taken[name] = name, true
	}
	return names
}

// comment writes text as // comment lines: every line break starts a new comment line and other
// control characters are dropped.
func comment(text string) string {
	var b strings.Builder
	for _, line := range lines(text) {
		b.WriteString(strings.TrimRight("// "+line, " ") + "\n")
	}
	return b.String()
}

func lines(text string) []string {
	text = strings.Map(func(r rune) rune {
		switch r {
		case '\r', '\n', '\u0085', ' ', ' ':
			return '\n'
		}
		if unicode.IsControl(r) || r == unicode.ReplacementChar {
			return -1
		}
		return r
	}, strings.ReplaceAll(text, "\r\n", "\n"))
	return strings.Split(text, "\n")
}

func doc(name string, f entitler.FeatureListing) string {
	title := f.Name
	if strings.TrimSpace(title) == "" {
		title = f.Key
	}
	paragraphs := []string{name + " is " + strings.Join(lines(title), " ") + "."}
	if strings.TrimSpace(f.Description) != "" {
		paragraphs = append(paragraphs, f.Description)
	}
	if strings.TrimSpace(f.Unit) != "" {
		paragraphs = append(paragraphs, "Counted in "+strings.Join(lines(f.Unit), " ")+".")
	}
	if f.Type == entitler.FeatureTypeGroup && len(f.Includes) > 0 {
		paragraphs = append(paragraphs, "Includes "+strings.Join(f.Includes, ", ")+".")
	}
	if f.Archived {
		paragraphs = append(paragraphs, "Deprecated: Archived in Entitler.")
	}
	return comment(strings.Join(paragraphs, "\n\n"))
}

func constructor(f entitler.FeatureListing, byKey map[string]entitler.FeatureListing) string {
	key := strconv.Quote(f.Key)
	switch f.Type {
	case entitler.FeatureTypeBoolean:
		return "entitler.OnOff(" + key + ")"
	case entitler.FeatureTypeConfig:
		return "entitler.Config(" + key + ")"
	case entitler.FeatureTypeMetered:
		return "entitler.Metered(" + key + ")"
	case entitler.FeatureTypeGroup:
		args := []string{key}
		for _, leaf := range leaves(f, byKey) {
			args = append(args, strconv.Quote(leaf))
		}
		return "entitler.Group(" + strings.Join(args, ", ") + ")"
	}
	return "entitler.Key(" + key + ")"
}

// leaves expands a group's includes into its leaf members: nested groups recursively, in
// first-seen order, without duplicates or unknown keys, stopping at cycles.
func leaves(group entitler.FeatureListing, byKey map[string]entitler.FeatureListing) []string {
	var out []string
	seen := map[string]bool{group.Key: true}
	var walk func(f entitler.FeatureListing)
	walk = func(f entitler.FeatureListing) {
		for _, key := range f.Includes {
			member, ok := byKey[key]
			if !ok || seen[key] {
				continue
			}
			seen[key] = true
			if member.Type == entitler.FeatureTypeGroup {
				walk(member)
				continue
			}
			out = append(out, key)
		}
	}
	walk(group)
	return out
}
